def text(x,y,s,size=9,bold=False,color='#263746',font=None):
 C.setFont(font or ('Bold' if bold else 'Font'),size);C.setFillColor(color);C.drawString(x*mm,y*mm,s)
def para(x,y,w,s,size=10):
 p=Paragraph(escape(s).replace('\n','<br/>'),ParagraphStyle('p',fontName='Font',fontSize=size,leading=size*1.42,textColor='#263746'));_,h=p.wrap(w*mm,900);p.drawOn(C,x*mm,y*mm-h);return h/mm
def page(title,subtitle):
 global page_no
 if page_no:C.showPage()
 page_no+=1;C.setFillColor('#faf9f6');C.rect(0,0,297*mm,210*mm,fill=1,stroke=0)
 C.setFillColor('#263746');C.rect(0,176*mm,297*mm,34*mm,fill=1,stroke=0)
